def md(cols, rows, n=16):
    f = lambda v: "" if v is None else (f"{v:.1f}" if isinstance(v, float) and v != int(v) else (str(int(v)) if isinstance(v, float) else str(v)))
    L = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)] + ["| " + " | ".join(f(v) for v in r) + " |" for r in rows[:n]]
    return "\n".join(L) + (f"\n\n(first {n} of {len(rows)} rows)" if len(rows) > n else "")
L = ["# OLAP queries (R3)", "", "15 queries in `sql/olap/*.sql`, run on the star schema in DuckDB (`python3 scripts/run_olap.py`; this file: `python3 scripts/make_doc_olap.py`). Each query has the business question, the SQL, the result and an interpretation. **The data are synthetic** (`etl/generate.py`), so the interpretations describe what the generator built in; they are not medical findings.", "",
     "Constructs used: ROLLUP (q01, q02, q11), CUBE (q03), GROUPING SETS (q04), slice (q05), dice (q06), PIVOT (q07), window functions – running total (q08), DENSE_RANK (q09), moving average (q10), drill-down class → subclass along the taxonomy (q11, q12, q15), SCD2 (q13, q15), semi-additive measure (q14).", ""]
for k, v in R.items():
    L += [f"## {k}", "", f"**Question.** {v['question']}", "", f"**Operation.** {v['operation']}", "", "```sql", (ROOT / "sql/olap" / f"{k}.sql").read_text().strip(), "```", "", f"**Result** ({len(v['rows'])} rows, {v['ms']} ms on 20 000 facts)", "", md(v["columns"], v["rows"]), "", f"**Interpretation.** {INTERP[k]}", ""]
L += ["## Independent verification with pandas", "", "`scripts/verify_olap.py` recomputes selected numbers from the Parquet files with pandas (merge + groupby, no SQL):", "", "| check | SQL | pandas | match |", "|---|---|---|---|"] + [f"| {o['check']} | {o['sql']:g} | {o['pandas']:g} | {'yes' if o['ok'] else 'NO'} |" for o in V] + ["", f"{sum(o['ok'] for o in V)} of {len(V)} checks agree (queries q01, q03, q09, q13 – four results, more than the required two)."]
(ROOT / "docs/olap_results.md").write_text("\n".join(L) + "\n", encoding="utf-8"); print("ok", len(R))
